click('[data-nav=\"draft\"]');assert.equal("'$('"'#invoice-rows').children.length,1);click('[data-detail=\"1044\"]');assert("'$('"'#update-status').textContent.includes('Mark as awaiting payment'));click('#update-status');assert("'$('"'#invoice-rows').textContent.includes('No invoices found'));assert.equal("'$('"'#outstanding-total').textContent,'"'$20,250.00'"');
